int a = 10;
int b = a;              // copies the value
b = 20;
Console.WriteLine($"a = {a}, b = {b}");

int[] first = [1, 2, 3];
int[] second = first;   // copies the reference, not the array
second[0] = 99;
Console.WriteLine($"first[0] = {first[0]}, second[0] = {second[0]}");

Point p1 = new Point(1, 2);
Point p2 = p1;          // a copy of the struct
p2.X = 50;
Console.WriteLine($"p1.X = {p1.X}, p2.X = {p2.X}");

Box b1 = new Box(1, 2);
Box b2 = b1;            // a second reference to the same object
b2.X = 50;
Console.WriteLine($"b1.X = {b1.X}, b2.X = {b2.X}");

struct Point
{
    public int X;
    public int Y;
    public Point(int x, int y) { X = x; Y = y; }
}

class Box
{
    public int X;
    public int Y;
    public Box(int x, int y) { X = x; Y = y; }
}

string s1 = "hello";
string s2 = s1;
s2 += " world";         // builds a new string and points s2 at it
Console.WriteLine(s1);
Console.WriteLine(s2);
Console.WriteLine(s1 == "hello");

double d = 0.1 + 0.2;
decimal m = 0.1m + 0.2m;

Console.WriteLine(d == 0.3);
Console.WriteLine(m == 0.3m);
Console.WriteLine(d);

int big = int.MaxValue;
Console.WriteLine(big);
Console.WriteLine(big + 1);     // wraps around silently

int? score = null;
Console.WriteLine(score.HasValue);
score = 88;
Console.WriteLine(score.HasValue);
Console.WriteLine(score ?? 0);

string? nickname = null;
Console.WriteLine(nickname ?? "(no nickname)");
Console.WriteLine(nickname?.Length ?? 0);

nickname ??= "ada";
Console.WriteLine(nickname.ToUpper());

int small = 42;
long big = small;             // implicit
double precise = small;       // implicit: 42 becomes 42.0

double pi = 3.99;
int truncated = (int)pi;      // explicit cast drops the fraction
Console.WriteLine(truncated);
Console.WriteLine(Math.Round(pi));

int number = int.Parse("123") + 1;
Console.WriteLine(number);

bool ok = int.TryParse("12x", out int parsed);
Console.WriteLine($"{ok} {parsed}");

Console.WriteLine(number.ToString().Length);
